import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Property visibility","description":"","frontmatter":{"title":"Property visibility","covers":{"screens":["SCR-032"],"stories":["US-124","US-125"]}},"headers":[],"relativePath":"administration/property-visibility.md","filePath":"administration/property-visibility.md"}`),s={name:`administration/property-visibility.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="property-visibility" tabindex="-1">Property visibility <a class="header-anchor" href="#property-visibility" aria-label="Permalink to “Property visibility”">​</a></h1><p>Some properties should not be visible to everyone who can read an entity, such as investment costs or a security classification. Security administration decides for each property who may see and write its values. You need the role <code>security-admin</code> (permission <code>visibility:configure</code>); metamodel administrators cannot change the visibility (see <a href="./roles-and-permissions">Roles and permissions</a>).</p><div class="warning custom-block"><p class="custom-block-title">Enforcement follows</p><p>In this version you configure the visibility. A property that is not <em>Public</em> stays hidden in catalogs and cannot be written until reading and writing it by role or connection follow in the next versions.</p></div><h2 id="the-page" tabindex="-1">The page <a class="header-anchor" href="#the-page" aria-label="Permalink to “The page”">​</a></h2><p>Open <em>Property visibility</em> in the header. The page lists every property with the entity types that use it, its visibility and its restriction; restricted properties carry the badge <em>Restricted</em>. Filter the list by name.</p>`,5),i(d,{name:`property-visibility`,alt:`Dialog for the visibility of a property with read and write roles`}),o[1]||=t(`<h2 id="change-the-visibility" tabindex="-1">Change the visibility <a class="header-anchor" href="#change-the-visibility" aria-label="Permalink to “Change the visibility”">​</a></h2><p>Click the pencil of a property and choose the visibility:</p><ul><li><strong>Public:</strong> everyone who can read the entity sees the value. This is the default of every property.</li><li><strong>Role-based:</strong> only holders of the chosen read roles see the value, and only holders of the chosen write roles may change it. Choose at least one read role; every write role must also be a read role. Without a write role nobody may change the value.</li><li><strong>Connection-based:</strong> only persons connected to the entity through the chosen connection type see and change the value, for example a domain architect connected through <em>Domain Assignment</em>. Only connection types can be chosen.</li></ul><p>The dialog shows only the fields of the chosen visibility and points out a missing selection before it saves. Every change is written to the audit log as <code>visibility.changed</code>; a change that grants one of your own roles is marked as self-benefiting.</p><p>As long as a connection type is used for a connection-based property, creating connections of that type needs the permission <code>visibility-scope:assign</code> (role <code>security-admin</code>), so that nobody grants themselves access. Such a connection type cannot be deleted.</p><p>In the metamodel configuration, restricted properties show the badge <em>Restricted</em>, and the dialog of a property shows its visibility read-only (see <a href="./metamodel-editing">Editing the metamodel</a>).</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><ul><li><p><code>GET /admin/property-visibility</code> lists the visibility of every property with <code>visibilityMode</code>, <code>readRoles</code>, <code>writeRoles</code>, <code>scopingConnectionType</code> and the entity types in <code>metatypes</code>.</p></li><li><p><code>PUT /admin/property-visibility</code> changes the listed properties in one step, for example:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --arg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[{propertyDefId: $id, visibilityMode: &quot;role-restricted&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  readRoles: [&quot;enterprise-architect&quot;, &quot;auditor&quot;], writeRoles: [&quot;enterprise-architect&quot;]}]&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/property-visibility&quot;</span></span></code></pre></div><p>An invalid entry answers <code>422</code> with the field in <code>invalidFields</code>, such as <code>[0].readRoles</code>, and nothing changes.</p></li></ul><p>Both need <code>visibility:configure</code>.</p>`,9)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};